options.css:
.container {
    font-family: 'Inter', Helvetica, Arial, sans-serif;
    text-align: center;
    width: 100%;
    padding: 32px 20px 48px;
}

.title {
    font-size: 30px;
    font-weight: 700;
    color: #1a1a1a;
    margin: 0 auto 10px;
    letter-spacing: -0.3px;
}

.info {
    font-size: 15px;
    color: #5a5a5a;
    margin: 0 auto 36px;
    line-height: 1.6;
    max-width: 520px;
}

.section-label {
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 2px;
    color: #aaa;
    margin: 36px 0 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
}

.section-label::before,
.section-label::after {
    content: '';
    flex: 1;
    max-width: 160px;
    height: 0.5px;
    background: rgba(0, 0, 0, 0.12);
}

a {
    text-decoration: none;
}

.fixed {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    width: 200px;
    margin: 8px;
    vertical-align: top;
}

.fixed .label {
    font-size: 13px;
    font-weight: 600;
    color: #585858;
    line-height: 1.4;
    text-align: center;
    min-height: 36px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0;
}

a:hover .label {
    color: #1a1a1a;
}

.met-table,
.met-map,
.rain-graph,
.rain-map,
.spw-plot,
.advanced-map,
.advanced-tables,
.forecast-explorer,
.kr-tracking,
.coming-soon {
    border-radius: 12px;
    width: 200px;
    height: 160px;
    margin: 0 auto;
    border: 0.5px solid rgba(0, 0, 0, 0.12);
    background-color: #f1f1f1;
    background-size: cover;
    background-position: center;
    position: relative;
    transition: border-color 0.18s ease, transform 0.18s ease;
}

a:hover .met-table,
a:hover .met-map,
a:hover .rain-graph,
a:hover .rain-map,
a:hover .spw-plot,
a:hover .advanced-map,
a:hover .forecast-explorer,
a:hover .advanced-tables,
a:hover .kr-tracking {
    border-color: rgba(0, 0, 0, 0.3);
    transform: translateY(-3px);
}

.coming-soon::after {
    content: "Coming soon";
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    color: #aaa;
}

.met-table {
    background-image: url("https://storage.googleapis.com/sheerwater-public/grafana_table_icon.png");
}

.met-map {
    background-image: url("https://storage.googleapis.com/sheerwater-public/multimap.png");
}

.advanced-map {
    background-image: url("https://storage.googleapis.com/sheerwater-public/multimap.png");
}

.advanced-tables {
    background-image: url("https://storage.googleapis.com/sheerwater-public/ag_tables.png");
}

.kr-tracking {
    background-image: url("https://storage.googleapis.com/sheerwater-public/actionable.png");
}


.forecast-explorer {
    background-image: url("https://storage.googleapis.com/sheerwater-public/rain-explorer.png");
}


.rain-graph {
    background-image: url("https://storage.googleapis.com/sheerwater-public/rainfall-graph.png");
}

.rain-map {
    background-image: url("https://storage.googleapis.com/sheerwater-public/rainmap.png");
}

.spw-plot {
    background-image: url("https://storage.googleapis.com/sheerwater-public/multimap.png");
}
